// Function to extract program items from current page
async function getPagePrograms() {
  return await browserjs(tabId, () => {
    // Select all result list items
    const items = [];
    const headings = document.querySelectorAll('main h3, main h4');
    for (const h of headings) {
      const a = h.querySelector('a');
      if (a && a.href.includes('/academics/')) {
        const parent = h.closest('li') || h.closest('.result-item') || h.parentElement;
        // extract metadata like Type, Duration, School
        items.push({
          title: a.textContent.trim(),
          url: a.href,
          fullText: parent.textContent.trim().replace(/\s+/g, ' ')
        });
      }
    }
    const resultCount = document.querySelector('main p')?.textContent?.trim().replace(/\s+/g, ' ') || '';
    return { resultCount, items };
  });
}

