async function getAllResults(baseUrl) {
  let allItems = [];
  let page = 1;
  while (true) {
    const pageUrl = page === 1 ? baseUrl : `${baseUrl}&page=${page}`;
    await tool.navigate({ tabId, url: pageUrl });
    await tool.wait_for({ tabId, condition: "load_state", value: "load" });

    const data = await browserjs(tabId, () => {
      const items = [];
      const headings = document.querySelectorAll('main h3, main h4');
      for (const h of headings) {
        const a = h.querySelector('a');
        if (a && a.href.includes('/academics/')) {
          const parent = h.closest('li') || h.closest('.result-item') || h.parentElement;
          items.push({
            title: a.textContent.trim(),
            url: a.href,
            fullText: parent.textContent.trim().replace(/\s+/g, ' ')
          });
        }
      }
      const hasNext = !!document.querySelector('a[href*="page=' + (page + 1) + '"]');
      return { items, hasNext };
    });

    allItems.push(...data.items);
    if (!data.hasNext || data.items.length === 0) break;
    page++;
  }
  return allItems;
}

