async function getFullProgramData() {
  const all = [];
  for (let page = 1; page <= 3; page++) {
    const url = page === 1 
      ? "https://college.mayo.edu/academics/?location=Florida&type=Internship" 
      : `https://college.mayo.edu/academics/?location=Florida&type=Internship&page=${page}`;
    await tool.navigate({ tabId, url });
    await tool.wait_for({ tabId, condition: "load_state", value: "load" });

    const pageItems = await browserjs(tabId, () => {
      const items = [];
      const blocks = document.querySelectorAll('main li, main .result-item');
      for (const block of blocks) {
        const link = block.querySelector('h3 a, h4 a');
        if (link && link.href.includes('/academics/')) {
          // parse the details lines
          const text = block.innerText || block.textContent;
          items.push({
            title: link.textContent.trim(),
            url: link.href,
            raw: text.trim().replace(/\r?\n+/g, ' | ')
          });
        }
      }
      return items;
    });
    all.push(...pageItems);
  }
  return all;
}

const internships = await getFullProgramData();
console.log("Collected", internships.length, "internship programs:");
internships.forEach((p, idx) => console.log(`${idx + 1}. ${p.title} (${p.url}) -> ${p.raw}`));

