const tabId = 118779795;

async function extractPrograms(url) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });

  return await browserjs(tabId, () => {
    const articles = document.querySelectorAll('article.program-search-result');
    return Array.from(articles).map(art => {
      const titleLink = art.querySelector('h3.program-title a');
      const details = Array.from(art.querySelectorAll('.program-details li')).map(li => li.textContent.trim().replace(/\s+/g, ' '));
      return {
        title: titleLink?.textContent?.trim(),
        url: titleLink?.href,
        details: details.join(' | ')
      };
    });
  });
}

